package udea.integrador.ingenote.infrastructure.adapter.out.persistence.repository;
import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import udea.integrador.ingenote.infrastructure.adapter.out.persistence.entity.ValoracionJpaEntity; import java.util.*;
